 struct Cr3Guard(Cr3Register);

 impl Drop for Cr3Guard {
     ///
     /// # Description
     ///
     /// Restores the previously active CR3 value saved in this guard.
     ///
     fn drop(&mut self) {
         // SAFETY: caller runs at privilege level 0; CR3 holds a valid PD address.
         unsafe {
             self.0.write();
         }

